UPDATE cs
SET cs.MinPT = s.MinPT
FROM dbo.CustPTSetting3rd_Agent cs WITH (ROWLOCK,UPDLOCK)
	INNER JOIN #CustList s ON s.CustID = cs.CustID
WHERE cs.SportType = @Sporttype

